import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/core/widgets/art_entrance.dart';

void main() {
  testWidgets('Reduced motion shows art immediately without a ticker', (tester) async {
    await tester.pumpWidget(const MediaQuery(
      data: MediaQueryData(disableAnimations: true),
      child: Directionality(textDirection: TextDirection.ltr,
        child: ArtEntrance(child: Text('Ready'))),
    ));
    expect(find.text('Ready'), findsOneWidget);
    expect(find.byType(TweenAnimationBuilder<double>), findsNothing);
    expect(tester.binding.hasScheduledFrame, isFalse);
  });
  testWidgets('Decorative entrance keeps actions available and disposes safely', (tester) async {
    var taps = 0;
    await tester.pumpWidget(MaterialApp(home: ArtEntrance(
      child: TextButton(onPressed: () => taps++, child: const Text('Continue')),
    )));
    await tester.tap(find.text('Continue'));
    expect(taps, 1);
    await tester.pumpWidget(const SizedBox());
    await tester.pump(const Duration(seconds: 1));
    expect(tester.takeException(), isNull);
  });
}

