void main() {
  late Directory temp;
  late SharedPreferences prefs;
  late ProviderContainer container;
  late List<Map<String, dynamic>> fixtureTree;
  setUpAll(() async {
    final fonts = FontLoader('Manrope');
    for (final weight in [400, 500, 600, 700, 800]) {
