    temp = await Directory.systemTemp.createTemp('hyzen-widget-test-');
    Hive.init(temp.path);
    for (final box in [
      Boxes.contentCache,
      Boxes.downloads,
      Boxes.recent,
      Boxes.cart,
      Boxes.myOrders,
      Boxes.externalHistory,
      Boxes.pdfStudioHistory,
    ]) {
      await Hive.openBox<String>(box);
    }
    final tree = <Map<String, dynamic>>[];
